#!/usr/bin/env python3
"""Bounded verification: compare the supplied CONSORT 2025 item table with the
official Table 1 of the CONSORT 2025 statement (local copy of PMC11995449).

Reads:  official-consort-2025.html, consort-2025.md   (both read-only)
Writes: consort-table-comparison.json

Exit code 0 when every official item number and item text is reproduced by the
supplied table (bullet glyph normalised), 1 otherwise.
"""
import hashlib
import html
import json
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
OFFICIAL = HERE / "official-consort-2025.html"
SUPPLIED = HERE / "consort-2025.md"
OUT = HERE / "consort-table-comparison.json"


def sha256(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def clean(s: str) -> str:
    s = re.sub(r"(?s)<[^>]+>", "", s)
    s = html.unescape(s)
    s = s.replace("\u00a0", " ")
    return re.sub(r"\s+", " ", s).strip()


def parse_official(raw: str):
    """Return (rows, table_span) from the single checklist table in the page."""
    i = raw.find('<table class="content"')
    if i < 0:
        raise SystemExit("checklist table not found in the official page")
    j = raw.find("</table>", i)
    table_html = raw[i : j + len("</table>")]
    rows = []
    section = None
    topic = None
    for tr in re.findall(r"(?s)<tr>(.*?)</tr>", table_html):
        cells = re.findall(r"(?s)<t[dh][^>]*>(.*?)</t[dh]>", tr)
        if not cells:
            continue
        texts = [clean(c) for c in cells]
        if len(cells) == 3 and 'colspan="3"' in tr:
            section = texts[0]
            topic = None
            continue
        if len(cells) == 2:  # continuation row: number + text (topic via rowspan)
            no, text = texts
            if not re.fullmatch(r"\d+[a-z]?", no):
                continue  # header row
        elif len(cells) == 3:
            topic, no, text = texts
            if no.lower() in ("no",):
                continue  # header row
        else:
            continue
        # byte offset of this item's description inside the page
        off = raw.find(html.escape(text[:40], quote=False), i, j)
        rows.append(
            {
                "section": section,
                "topic": topic,
                "item": no,
                "text": text,
                "pageCharOffset": off,
            }
        )
    return rows, {"start": i, "end": j + len("</table>")}


def parse_supplied(raw: str):
    rows = []
    for line in raw.splitlines():
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) != 4 or cells[1] in ("Item", "---"):
            continue
        if set(cells[1]) <= {"-"}:
            continue
        rows.append({"sectionTopic": cells[0], "item": cells[1], "text": cells[2]})
    return rows


def norm_text(s: str) -> str:
    return re.sub(r"\s+", " ", s.replace("\u25cf", "\u2022")).strip()


def main() -> int:
    raw_official = OFFICIAL.read_text(encoding="utf-8", errors="replace")
    raw_supplied = SUPPLIED.read_text(encoding="utf-8")
    official, span = parse_official(raw_official)
    supplied = parse_supplied(raw_supplied)

    by_no = {r["item"]: r for r in official}
    sup_by_no = {r["item"]: r for r in supplied}

    diffs = []
    for no in list(by_no):
        if no not in sup_by_no:
            diffs.append({"item": no, "kind": "missing_from_supplied"})
            continue
        o, s = by_no[no], sup_by_no[no]
        if o["text"] != s["text"]:
            diffs.append(
                {
                    "item": no,
                    "kind": "text_differs_verbatim",
                    "official": o["text"],
                    "supplied": s["text"],
                    "equal_after_bullet_normalisation": norm_text(o["text"])
                    == norm_text(s["text"]),
                }
            )
    for no in list(sup_by_no):
        if no not in by_no:
            diffs.append({"item": no, "kind": "present_in_supplied_only"})

    seq_equal = [r["item"] for r in official] == [r["item"] for r in supplied]

    # inventory of sub-item families, to test any claim about 8a/8b/8c
    families = {}
    for r in official:
        m = re.fullmatch(r"(\d+)([a-z]?)", r["item"])
        families.setdefault(m.group(1), []).append(r["item"])

    report = {
        "comparison": "supplied CONSORT 2025 item table vs Table 1 of the CONSORT 2025 statement",
        "officialSource": {
            "file": OFFICIAL.name,
            "sha256": sha256(OFFICIAL),
            "bytes": OFFICIAL.stat().st_size,
            "pmcid": "PMC11995449",
            "citation": "Hopewell S, Chan AW, Collins GS, et al. CONSORT 2025 statement: updated guideline for reporting randomised trials. BMJ 2025;389:e081123. doi:10.1136/bmj-2024-081123",
            "tableCharSpan": span,
        },
        "suppliedSource": {"file": SUPPLIED.name, "sha256": sha256(SUPPLIED)},
        "officialItemCount": len(official),
        "suppliedItemCount": len(supplied),
        "itemNumberSequenceIdentical": seq_equal,
        "differences": diffs,
        "verbatimTextMatches": len([r for r in official if r["item"] in sup_by_no and r["text"] == sup_by_no[r["item"]]["text"]]),
        "itemFamiliesInOfficialTable": families,
        "subItemsOfItem8": families.get("8", []),
        "olderStyle8a8b8cPresent": any(x in by_no for x in ("8a", "8b", "8c")),
        "mappedItems": {
            k: {"topic": by_no[k]["topic"], "section": by_no[k]["section"], "text": by_no[k]["text"], "pageCharOffset": by_no[k]["pageCharOffset"]}
            for k in ("3", "17a", "17b", "18", "20a", "20b", "22b")
            if k in by_no
        },
    }
    OUT.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    print(f"official items={len(official)} supplied items={len(supplied)} sequence identical={seq_equal}")
    print(f"verbatim text matches={report['verbatimTextMatches']}")
    for d in diffs:
        print(" DIFF", d["item"], d["kind"], "(equal after bullet normalisation: %s)" % d.get("equal_after_bullet_normalisation"))
    print("item 8 sub-items in official table:", families.get("8"))
    print("any 8a/8b/8c in official table:", report["olderStyle8a8b8cPresent"])
    print("wrote", OUT)
    hard_fail = [d for d in diffs if d["kind"] in ("missing_from_supplied", "present_in_supplied_only")] or not seq_equal
    text_fail = [d for d in diffs if d["kind"] == "text_differs_verbatim" and not d.get("equal_after_bullet_normalisation")]
    return 1 if (hard_fail or text_fail) else 0


if __name__ == "__main__":
    sys.exit(main())

