#!/usr/bin/env python3
"""Build checklist.json for the bounded CONSORT 2025 mapping.

Official item wording and page offsets are not typed: they are read from
consort-table-comparison.json, which is produced by parsing the official
paper's Table 1 directly, so every item text in the output is byte-identical
to the official table.

Reads:  consort-table-comparison.json, teaching-excerpts.txt
Writes: checklist.json
"""
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
RULES = {
    "stated": "the excerpt contains a statement that directly answers this element",
    "partially_stated": "the excerpt answers the element for part of its scope (one role, one part of a multi-part element) and leaves the rest unstated",
    "not_stated": "the excerpt contains no statement answering this element; a quote may still be attached as relatedStatement when the excerpt says something adjacent",
}

ITEMS = [
    {
        "item": "17a",
        "elements": ["who generated the random allocation sequence", "the method used"],
        "byStudy": {
            "S1": {
                "who generated the random allocation sequence": {
                    "state": "not_stated",
                    "note": "No person or body that generated the allocation sequence is named. The rule the excerpt describes executes itself on the day of entry and has no separate generator.",
                },
                "the method used": {
                    "state": "stated",
                    "quote": "Participants were allocated alternately by day.",
                    "note": "The method stated is alternation by day of entry. Alternation is a predictable, non-random rule; what is reported here is a method of allocation, not a method of random allocation, so this item is not satisfied by randomisation.",
                },
            },
            "S2": {
                "who generated the random allocation sequence": {
                    "state": "not_stated",
                    "note": "The excerpt states that the sequence was computer-generated but names no person, unit or system responsible for generating it.",
                },
                "the method used": {
                    "state": "stated",
                    "quote": "A computer-generated sequence assigned 60 participants equally.",
                    "note": "The stated method is computer generation, with 60 participants assigned equally.",
                },
            },
        },
    },
    {
        "item": "17b",
        "elements": ["type of randomisation", "details of any restriction (eg, stratification, blocking and block size)"],
        "byStudy": {
            "S1": {
                "type of randomisation": {
                    "state": "not_stated",
                    "relatedStatement": "Participants were allocated alternately by day.",
                    "note": "No type of randomisation is stated. The allocation rule given is alternation by day, which is not a randomisation type; it is recorded here rather than converted into one.",
                },
                "details of any restriction (eg, stratification, blocking and block size)": {
                    "state": "not_stated",
                    "note": "No stratification, blocking or block size is stated.",
                },
            },
            "S2": {
                "type of randomisation": {
                    "state": "not_stated",
                    "relatedStatement": "A computer-generated sequence assigned 60 participants equally.",
                    "note": "The excerpt names the sequence method, not a randomisation type (for example parallel-group); the type is left unstated.",
                },
                "details of any restriction (eg, stratification, blocking and block size)": {
                    "state": "not_stated",
                    "relatedStatement": "A computer-generated sequence assigned 60 participants equally.",
                    "note": "Equal assignment of the 60 participants concerns group sizes; nothing is stated about stratification, blocking or block size.",
                },
            },
        },
    },
    {
        "item": "18",
        "elements": [
            "mechanism used to implement the random allocation sequence",
            "steps to conceal the sequence until interventions were assigned",
        ],
        "byStudy": {
            "S1": {
                "mechanism used to implement the random allocation sequence": {
                    "state": "not_stated",
                    "relatedStatement": "Participants were allocated alternately by day.",
                    "note": "No implementation mechanism (for example a central service, or sequentially numbered sealed containers) is stated. Alternation by day is an open, predictable rule; it is recorded as the closest statement and no concealment mechanism is inferred from it.",
                },
                "steps to conceal the sequence until interventions were assigned": {
                    "state": "not_stated",
                    "note": "No step to conceal the sequence is stated.",
                },
            },
            "S2": {
                "mechanism used to implement the random allocation sequence": {
                    "state": "not_stated",
                    "relatedStatement": "Allocation concealment was not described.",
                    "note": "The excerpt states that concealment was not described. That is a gap in the report; it is not evidence that concealment was absent, and it supplies no mechanism.",
                },
                "steps to conceal the sequence until interventions were assigned": {
                    "state": "not_stated",
                    "note": "No step to conceal the sequence is stated; the excerpt says only that concealment was not described.",
                },
            },
        },
    },
    {
        "item": "20a",
        "elements": ["who was blinded after assignment to interventions"],
        "byStudy": {
            "S1": {
                "who was blinded after assignment to interventions": {
                    "state": "partially_stated",
                    "quote": "Outcome assessors knew allocation.",
                    "note": "One role is addressed and its status is given as knowing the allocation, so outcome assessors were not blinded. Participants, care providers and data analysts are not addressed, so who (if anyone) was blinded is not fully stated.",
                },
            },
            "S2": {
                "who was blinded after assignment to interventions": {
                    "state": "partially_stated",
                    "quote": "Outcome assessors were blinded.",
                    "note": "One role is stated as blinded. Participants, care providers and data analysts are not addressed.",
                },
            },
        },
    },
    {
        "item": "20b",
        "elements": ["how blinding was achieved", "description of the similarity of interventions"],
        "byStudy": {
            "S1": {
                "how blinding was achieved": {
                    "state": "not_stated",
                    "relatedStatement": "Outcome assessors knew allocation.",
                    "note": "On the excerpt's own statement the assessors were not blinded, and no method of blinding is given in any case.",
                },
                "description of the similarity of interventions": {
                    "state": "not_stated",
                    "note": "Nothing about the interventions or their similarity is stated.",
                },
            },
            "S2": {
                "how blinding was achieved": {
                    "state": "not_stated",
                    "relatedStatement": "Outcome assessors were blinded.",
                    "note": "That assessors were blinded is stated; how blinding was achieved is not.",
                },
                "description of the similarity of interventions": {
                    "state": "not_stated",
                    "note": "Nothing about the interventions or their similarity is stated.",
                },
            },
        },
    },
    {
        "item": "22b",
        "elements": [
            "losses and exclusions after randomisation",
            "reasons for the losses and exclusions",
            "for each group",
        ],
        "byStudy": {
            "S1": {
                "losses and exclusions after randomisation": {
                    "state": "not_stated",
                    "note": "No losses, exclusions or follow-up numbers appear in the excerpt.",
                },
                "reasons for the losses and exclusions": {
                    "state": "not_stated",
                    "note": "No losses or exclusions are stated, so no reasons can be either.",
                },
                "for each group": {
                    "state": "not_stated",
                    "note": "The excerpt names no groups.",
                },
            },
            "S2": {
                "losses and exclusions after randomisation": {
                    "state": "stated",
                    "quote": "Attrition was 12/60 without reasons.",
                    "note": "A single loss count of 12 of 60 is given for the trial as a whole. Losses and exclusions are not separated, and the excerpt does not say whether the 12 were included in any analysis.",
                },
                "reasons for the losses and exclusions": {
                    "state": "not_stated",
                    "relatedStatement": "Attrition was 12/60 without reasons.",
                    "note": "The excerpt states that reasons were not given; no reason is supplied.",
                },
                "for each group": {
                    "state": "not_stated",
                    "note": "The 12 are not split by group, and the excerpt does not say whether any exclusions occurred.",
                },
            },
        },
    },
    {
        "item": "3",
        "elements": [
            "where the trial protocol can be accessed",
            "where the statistical analysis plan can be accessed",
        ],
        "byStudy": {
            "S1": {
                "where the trial protocol can be accessed": {
                    "state": "not_stated",
                    "relatedStatement": "No prespecified protocol was provided.",
                    "note": "The excerpt states that no prespecified protocol was provided. That is a statement about prespecification, not an access location for a protocol; whether a protocol exists that can be accessed is left unstated.",
                },
                "where the statistical analysis plan can be accessed": {
                    "state": "not_stated",
                    "note": "No statistical analysis plan and no access location for one is stated.",
                },
            },
            "S2": {
                "where the trial protocol can be accessed": {
                    "state": "not_stated",
                    "note": "No protocol, registration record or access location is stated anywhere in the excerpt.",
                },
                "where the statistical analysis plan can be accessed": {
                    "state": "not_stated",
                    "note": "No statistical analysis plan and no access location for one is stated.",
                },
            },
        },
    },
]

ITEM_ORDER = ["17a", "17b", "18", "20a", "20b", "22b", "3"]


def main() -> None:
    comp = json.loads((HERE / "consort-table-comparison.json").read_text(encoding="utf-8"))
    official = comp["mappedItems"]
    excerpts_file = (HERE / "teaching-excerpts.txt").read_text(encoding="utf-8")
    excerpts = dict(line.split(" = ", 1) for line in excerpts_file.strip().splitlines())

    # quotes must be exact substrings of the excerpt they are attributed to
    problems = []
    for spec in ITEMS:
        for sid, states in spec["byStudy"].items():
            for el, st in states.items():
                for key in ("quote", "relatedStatement"):
                    if key in st and st[key] not in excerpts[sid]:
                        problems.append(f"{spec['item']}/{sid}/{el}: {key} not found verbatim in {sid}")
    if problems:
        raise SystemExit("quote check failed:\n" + "\n".join(problems))

    items_out = []
    for spec in ITEMS:
        no = spec["item"]
        off = official[no]
        items_out.append(
            {
                "consortItem": no,
                "officialSection": off["section"],
                "officialTopic": off["topic"],
                "officialItemText": off["text"],
                "officialPageCharOffset": off["pageCharOffset"],
                "elements": spec["elements"],
                "byStudy": spec["byStudy"],
            }
        )

    # counts, computed here rather than written by hand
    states = {"stated": 0, "partially_stated": 0, "not_stated": 0}
    per_study = {"S1": dict(states), "S2": dict(states)}
    for it in items_out:
        for sid, el_states in it["byStudy"].items():
            for st in el_states.values():
                states[st["state"]] += 1
                per_study[sid][st["state"]] += 1
    element_total = sum(states.values())
    pair_total = len(items_out) * len(per_study)

    def pct(n: int, d: int) -> float:
        return round(100.0 * n / d, 1)

    out = {
        "artifact": "reporting-checklist mapping",
        "guideline": "CONSORT 2025",
        "guidelineCitation": comp["officialSource"]["citation"],
        "scope": "Bounded partial mapping against two invented teaching excerpts (S1, S2) supplied by the requester. Seven item numbers named in the request are mapped: 17a, 17b, 18, 20a, 20b, 22b and 3. This is not a complete CONSORT checklist, not a statement of compliance, quality or publication readiness, and not a claim about any real trial. No item outside the two excerpts is inferred and no literature search was performed.",
        "sourceVerification": {
            "officialItemTable": {
                "pmcid": "PMC11995449",
                "file": comp["officialSource"]["file"],
                "sha256": comp["officialSource"]["sha256"],
                "tableCharacterSpan": comp["officialSource"]["tableCharSpan"],
                "itemsInTable": comp["officialItemCount"],
            },
            "suppliedItemTable": {
